SELECT jsonb_build_object('read13_marker','TrackUsageCounter/positive/B'::text,'position','BEFORE'::text);
SELECT jsonb_build_object('model','TrackUsageCounter','ids',coalesce(jsonb_agg(observed.id::text ORDER BY observed.id::text COLLATE "C"),'[]'::jsonb)) FROM (SELECT id,user_id,subscription_id,entitlement_grant_id,entitlement_id,track,period,customer_profile_id,candidate_profile_id,professional_profile_id,period_start,period_end,used_quantity,limit_quantity,updated_at,created_at,revision,source_revision,mutation_transaction_id FROM app.track_usage_counters WHERE id IN ('00296ab5-920d-5e01-ba1f-52689a0413fb'::uuid,'d55bbb10-78bd-59aa-8d4a-f72ae33bd675'::uuid)) observed;
SET CONSTRAINTS ALL IMMEDIATE;
SELECT jsonb_build_object('read13_marker','TrackUsageCounter/positive/B'::text,'position','AFTER'::text);
